/**
 * 웅진IT 퍼블리싱 UI 공통 스크립트
 */

document.addEventListener("DOMContentLoaded", () => {
    initPageTitle();
    initHeader();
    initHeaderAutoHide();
    initMobileGnb();
    initPcGnb();
    initSearchLayer();
    initFamilySite();
    initEmailDomain();
    initInflowSelect();
    initCategoryPanels();
    initTabMenu();
    initBridgeTabs();
    initCompanyTab();
    initFaqAccordion();
    initProjectCaseAccordion();
    initLayerPopupEvents();
    initIndustrySliders();
    initServiceItemCycle();
    initScrollTop();
    initHashScroll();
});

/* ==========================================================================
   0. 페이지 타이틀 등장 애니메이션 (Page Title)
   ========================================================================== */
function initPageTitle() {
    const title = document.querySelector("main > .title");
    if (!title) return;

    requestAnimationFrame(() => {
        title.classList.add("act");
    });
}

/* ==========================================================================
   1. 헤더 스크롤 감지 (Header Scroll Effect)
   ========================================================================== */
function initHeader() {
    const header = document.querySelector("header");
    if (!header) return;

    const handleScroll = () => {
        const scrollTop = window.scrollY || document.documentElement.scrollTop;
        if (scrollTop > 10) {
            header.classList.add("is-scrolled");
        } else {
            header.classList.remove("is-scrolled");
        }
    };

    window.addEventListener("scroll", handleScroll, { passive: true });
    handleScroll();
}

/* ==========================================================================
   1-1. 탭 페이지 헤더 자동 숨김 (Header Auto Hide with Sticky Tab)
   - 탭(.tab-list) 또는 카테고리(.category-list)가 헤더 아래에 고정된 이후
     · 아래로 스크롤: 헤더 숨김 + 탭 top 0
     · 위로 스크롤: 헤더 노출 + 탭 헤더 바로 아래
   - 탭 클릭 이동 중에는 헤더 상태를 도착 상태로 미리 고정(lock)하여 도착 후 위치 보정(튐) 없음
   ========================================================================== */
let headerAutoHide = null;

// 문서 기준 top (border-box)
function getDocTop(element) {
    return element.getBoundingClientRect().top + window.scrollY;
}

// sticky 요소의 고정 전(원래 위치) 문서 기준 top — sticky 상태와 무관하게 계산
function getStickyNaturalTop(element) {
    const prev = element.previousElementSibling;
    if (prev) {
        const prevMarginBottom = parseFloat(window.getComputedStyle(prev).marginBottom) || 0;
        return prev.getBoundingClientRect().bottom + window.scrollY + prevMarginBottom;
    }

    const parent = element.parentElement;
    const parentStyle = window.getComputedStyle(parent);
    const parentBorderTop = parseFloat(parentStyle.borderTopWidth) || 0;
    const parentPaddingTop = parseFloat(parentStyle.paddingTop) || 0;
    return getDocTop(parent) + parentBorderTop + parentPaddingTop;
}

function initHeaderAutoHide() {
    const header = document.querySelector("header");
    const tabList = document.querySelector(".tab-list, .category-list");
    if (!header || !tabList) return;

    const root = document.documentElement;
    const SCROLL_DIR_EPS = 2;
    let hidden = false;
    let locked = false;
    let lastScrollY = window.scrollY;
    let ticking = false;

    const getHeaderHeight = () => header.offsetHeight;

    // 탭이 뷰포트 상단에 닿은 뒤에 헤더를 숨긴다.
    // 헤더 높이만큼 일찍 숨기면 sticky top이 0이 되어, 탭이 헤더 아래에 처음 닿는 구간에서 고정되지 않는다.
    const isPastTab = (scrollY) => scrollY > 0 && scrollY >= getStickyNaturalTop(tabList) - 1;

    // 모바일 GNB · 검색 레이어 · 키보드 포커스가 헤더 안에 있으면 숨기지 않음
    const isHeaderBusy = () =>
        header.classList.contains("act") ||
        document.body.classList.contains("no-scroll") ||
        Boolean(header.querySelector(":focus-visible"));

    const apply = (nextHidden) => {
        hidden = nextHidden;
        header.classList.toggle("is-hide", hidden);
        root.style.setProperty("--sticky-tab-top", `${hidden ? 0 : getHeaderHeight()}px`);
    };

    const sync = () => {
        ticking = false;
        // iOS 바운스(오버스크롤) 구간은 범위 내로 보정 — 상·하단 튕김 시 방향 반전으로 헤더·탭이 깜빡이지 않도록
        const scrollY = Math.min(getMaxScroll(), Math.max(0, window.scrollY));
        const delta = scrollY - lastScrollY;

        if (!locked) {
            let nextHidden = hidden;
            if (!isPastTab(scrollY) || isHeaderBusy()) {
                nextHidden = false;
            } else if (delta > SCROLL_DIR_EPS) {
                nextHidden = true;
            } else if (delta < -SCROLL_DIR_EPS) {
                nextHidden = false;
            }
            if (nextHidden !== hidden) apply(nextHidden);
        }

        // 느린 스크롤도 방향이 누적되도록 임계값 이상 이동했을 때만 기준점 갱신
        if (Math.abs(delta) > SCROLL_DIR_EPS) lastScrollY = scrollY;
    };

    const requestSync = () => {
        if (ticking) return;
        ticking = true;
        requestAnimationFrame(sync);
    };

    header.classList.add("is-auto-hide");
    window.addEventListener("scroll", requestSync, { passive: true });
    window.addEventListener("resize", () => {
        apply(hidden);
        requestSync();
    });

    headerAutoHide = {
        // 헤더 숨김 여부에 따른 탭 고정 top
        getTabTop: (isHeaderHidden = hidden) => (isHeaderHidden ? 0 : getHeaderHeight()),
        // 탭 클릭 이동 — 도착 상태로 헤더를 먼저 전환하고 이동 중 방향 감지 중지
        lock: (nextHidden) => {
            locked = true;
            apply(nextHidden);
        },
        unlock: () => {
            locked = false;
            lastScrollY = window.scrollY;
        }
    };

    apply(false);
    sync();
}

function getMaxScroll() {
    return Math.max(0, document.documentElement.scrollHeight - window.innerHeight);
}

// 요소별 추가 sticky 오프셋 (--sticky-offset, px·rem) — 예: 카테고리 아래 2단 탭(.company-tab)
function getStickyOffset(element) {
    const raw = window.getComputedStyle(element).getPropertyValue("--sticky-offset").trim();
    const value = parseFloat(raw);
    if (!value) return 0;
    if (raw.endsWith("rem")) {
        return value * (parseFloat(window.getComputedStyle(document.documentElement).fontSize) || 10);
    }
    return value;
}

// 헤더 숨김 여부에 따른 sticky 탭 고정 top (헤더 자동 숨김 미적용 시 CSS top 사용)
function getStickyTabTop(element, isHeaderHidden) {
    if (!headerAutoHide) return parseFloat(window.getComputedStyle(element).top) || 0;
    return headerAutoHide.getTabTop(isHeaderHidden) + getStickyOffset(element);
}

/**
 * 탭 클릭 이동 공통 스크롤
 * - 이동 방향으로 도착 시 헤더 상태를 먼저 확정(아래: 숨김 / 위: 노출)하고 이동 → 도착 후 위치 보정(튐) 없음
 * - getTargetTop(isHeaderHidden): 헤더 상태별 목표 scrollTop
 * - options.forceHeaderHidden: 도착 시 헤더를 숨긴 채로 고정 (type2 탭)
 * - 이동 중 사용자가 직접 스크롤(휠·터치·키)하면 즉시 종료
 */
let cancelScrollWithHeader = null;

function scrollWithHeader(getTargetTop, onEnd, options) {
    if (cancelScrollWithHeader) cancelScrollWithHeader();

    const forceHeaderHidden = Boolean(options && options.forceHeaderHidden);
    const clampTop = (top) => Math.min(getMaxScroll(), Math.max(0, Math.round(top)));
    const rawHiddenTop = getTargetTop(true);
    const downTop = clampTop(rawHiddenTop);
    // type2는 위로 올라가 탭에 붙을 때도 헤더를 다시 열지 않는다. 페이지가 짧아 그 위치에 닿지 못하면 기존 방향 규칙을 따른다.
    const canStickHidden = downTop + 1 >= Math.round(rawHiddenTop);
    const isHeaderHidden = Boolean(headerAutoHide) && (
        forceHeaderHidden ? canStickHidden : downTop > window.scrollY + 1
    );
    const targetTop = isHeaderHidden ? downTop : clampTop(getTargetTop(false));
    const USER_EVENTS = ["wheel", "touchstart", "keydown"];
    let idleTimer = null;

    const end = () => {
        clearTimeout(idleTimer);
        window.removeEventListener("scroll", onProgress);
        window.removeEventListener("scrollend", end);
        USER_EVENTS.forEach((type) => window.removeEventListener(type, end));
        cancelScrollWithHeader = null;
        if (headerAutoHide) headerAutoHide.unlock();
        if (onEnd) onEnd();
    };

    // scrollend 미지원 브라우저 대비 — 스크롤 이벤트가 150ms 없으면 종료
    function onProgress() {
        clearTimeout(idleTimer);
        idleTimer = setTimeout(end, 150);
    }

    cancelScrollWithHeader = end;
    if (headerAutoHide) headerAutoHide.lock(isHeaderHidden);

    window.addEventListener("scroll", onProgress, { passive: true });
    window.addEventListener("scrollend", end);
    USER_EVENTS.forEach((type) => window.addEventListener(type, end, { passive: true }));
    onProgress();

    window.scrollTo({ top: targetTop, behavior: "smooth" });
}

/* ==========================================================================
   1-2. 주소 해시(#id) 스크롤
   - 주소에 id가 있으면 브라우저가 해당 요소로 스크롤한다
   - #sapJoule 은 sticky 탭에 가리지 않도록 목표 위치에서 tab-list 높이만큼 뺀다
   ========================================================================== */
function getHashId() {
    const raw = (location.hash || "").replace(/^#/, "");
    if (!raw) return "";
    try {
        return decodeURIComponent(raw);
    } catch (error) {
        return raw;
    }
}

function applySapJouleScrollMargin() {
    const target = document.getElementById("sapJoule");
    const tabList = document.querySelector(".tab-list");
    if (!target || !tabList) return 0;

    const offset = tabList.offsetHeight;
    target.style.scrollMarginTop = `${offset}px`;
    return offset;
}

function initHashScroll() {
    const scrollToSapJoule = () => {
        if (getHashId() !== "sapJoule") return;

        const target = document.getElementById("sapJoule");
        if (!target) return;

        const offset = applySapJouleScrollMargin();
        scrollWithHeader(
            () => getDocTop(target) - offset,
            null,
            { forceHeaderHidden: true }
        );
    };

    applySapJouleScrollMargin();
    window.addEventListener("resize", applySapJouleScrollMargin);
    window.addEventListener("hashchange", scrollToSapJoule);
    window.addEventListener("load", scrollToSapJoule);
    if (document.readyState === "complete") scrollToSapJoule();
}

/* ==========================================================================
   2. 모바일 GNB & 아코디언 메뉴 (Mobile GNB & Accordion)
   ========================================================================== */
function initMobileGnb() {
    const moGnbBtn = document.querySelector(".mo-menu");
    const moGnb = document.querySelector(".mo-gnb");
    const header = document.querySelector("header");
    if (!moGnbBtn || !moGnb) return;

    const slideDuration = 300;

    // 슬라이드 다운 애니메이션
    const slideDown = (target) => {
        if (!target) return;
        target.style.removeProperty("display");
        let display = window.getComputedStyle(target).display;
        if (display === "none") display = "block";
        target.style.display = display;

        const height = target.scrollHeight;
        target.style.overflow = "hidden";
        target.style.height = "0px";
        target.style.transition = `height ${slideDuration}ms ease-in-out`;

        target.offsetHeight; // Reflow 강제 실행

        target.style.height = height + "px";

        const onTransitionEnd = () => {
            target.style.removeProperty("height");
            target.style.removeProperty("overflow");
            target.style.removeProperty("transition");
            target.removeEventListener("transitionend", onTransitionEnd);
        };
        target.addEventListener("transitionend", onTransitionEnd);
    };

    // 슬라이드 업 애니메이션
    const slideUp = (target) => {
        if (!target) return;
        target.style.overflow = "hidden";
        target.style.height = target.scrollHeight + "px";
        target.style.transition = `height ${slideDuration}ms ease-in-out`;

        target.offsetHeight; // Reflow 강제 실행

        target.style.height = "0px";

        const onTransitionEnd = () => {
            target.style.display = "none";
            target.style.removeProperty("height");
            target.style.removeProperty("overflow");
            target.style.removeProperty("transition");
            target.removeEventListener("transitionend", onTransitionEnd);
        };
        target.addEventListener("transitionend", onTransitionEnd);
    };

    // 하위 서브메뉴 모두 닫기
    const closeSubMenu = (li) => {
        const activeLinks = li.querySelectorAll("a.act");
        activeLinks.forEach((a) => {
            a.classList.remove("act");
            a.setAttribute("aria-expanded", "false");
        });

        const openUls = li.querySelectorAll("ul");
        openUls.forEach((ul) => {
            if (window.getComputedStyle(ul).display !== "none") {
                slideUp(ul);
            }
        });
    };

    // 모바일 GNB 상태 초기화
    const resetMoGnb = () => {
        const activeLinks = moGnb.querySelectorAll("a.act");
        activeLinks.forEach((a) => {
            a.classList.remove("act");
            a.setAttribute("aria-expanded", "false");
        });

        const subUls = moGnb.querySelectorAll("ul ul");
        subUls.forEach((ul) => {
            ul.style.display = "none";
            ul.style.removeProperty("height");
            ul.style.removeProperty("overflow");
            ul.style.removeProperty("transition");
        });
        moGnb.scrollTop = 0;
    };

    // 모바일 메뉴 열기/닫기 토글
    moGnbBtn.addEventListener("click", () => {
        const isOpening = !moGnbBtn.classList.contains("act");
        moGnbBtn.classList.toggle("act", isOpening);
        moGnbBtn.setAttribute("aria-expanded", isOpening ? "true" : "false");
        moGnb.classList.toggle("act", isOpening);
        if (header) header.classList.toggle("act", isOpening);

        // 검색 레이어가 열려 있다면 닫기
        const searchLayer = document.querySelector(".search-layer");
        const searchBtn = document.querySelector(".function-menu .search");
        if (searchLayer && searchLayer.classList.contains("act")) {
            searchLayer.classList.remove("act");
            if (searchBtn) searchBtn.classList.remove("act");
        }

        // 바디 스크롤 락
        document.body.classList.toggle("no-scroll", isOpening);

        if (!isOpening) {
            resetMoGnb();
        }
    });

    // 모바일 아코디언 메뉴 클릭 이벤트
    const moGnbLinks = moGnb.querySelectorAll("a");
    moGnbLinks.forEach((link) => {
        const subMenu = link.nextElementSibling;
        if (subMenu && subMenu.tagName === "UL") {
            link.setAttribute("role", "button");
            link.setAttribute("aria-expanded", "false");

            link.addEventListener("click", (e) => {
                e.preventDefault();
                const parentLi = link.closest("li");
                const isOpening = !link.classList.contains("act");

                // 형제 서브메뉴 닫기 (아코디언 형태)
                if (parentLi && parentLi.parentElement) {
                    const siblingLis = Array.from(parentLi.parentElement.children).filter(
                        (child) => child !== parentLi && child.tagName === "LI"
                    );
                    siblingLis.forEach((siblingLi) => {
                        closeSubMenu(siblingLi);
                    });
                }

                if (isOpening) {
                    link.classList.add("act");
                    link.setAttribute("aria-expanded", "true");
                    slideDown(subMenu);
                } else {
                    link.classList.remove("act");
                    link.setAttribute("aria-expanded", "false");
                    slideUp(subMenu);

                    const childActiveLinks = subMenu.querySelectorAll("a.act");
                    childActiveLinks.forEach((a) => {
                        a.classList.remove("act");
                        a.setAttribute("aria-expanded", "false");
                    });

                    const childUls = subMenu.querySelectorAll("ul");
                    childUls.forEach((ul) => {
                        ul.style.display = "none";
                        ul.style.removeProperty("height");
                        ul.style.removeProperty("overflow");
                        ul.style.removeProperty("transition");
                    });
                }
            });
        }
    });

    // PC 해상도로 리사이즈 시 모바일 메뉴 초기화 및 닫기
    window.addEventListener("resize", () => {
        if (window.innerWidth > 1024) {
            if (moGnbBtn.classList.contains("act")) {
                moGnbBtn.classList.remove("act");
                moGnbBtn.setAttribute("aria-expanded", "false");
                moGnb.classList.remove("act");
                if (header) header.classList.remove("act");
                document.body.classList.remove("no-scroll");
                resetMoGnb();
            }
        }
    });
}

/* ==========================================================================
   3. PC GNB 네비게이션 (PC GNB Hover & Focus)
   ========================================================================== */
function initPcGnb() {
    const pcGnb = document.querySelector(".pc-gnb");
    const pcGnbList = document.querySelectorAll(".pc-gnb > ul > li");
    if (!pcGnb || !pcGnbList.length) return;
    const header = pcGnb.closest("header");

    const gnbSubs = Array.from(pcGnbList, (item) => item.querySelector(".gnb-sub")).filter(Boolean);
    const CLOSE_DURATION = 300; // common.css .gnb-sub.is-closing transition 시간
    let currentSub = null;
    let closeTimer = null;

    // transition 없이 즉시 스타일 적용 (닫힘 효과 중이면 함께 해제)
    const setInstant = (gnbSub, height, visibility) => {
        gnbSub.style.transition = "none";
        gnbSub.classList.remove("is-closing");
        gnbSub.style.height = height;
        gnbSub.style.visibility = visibility;
        void gnbSub.offsetHeight; // reflow
        gnbSub.style.transition = "";
    };

    const openGnbSub = (gnbSub) => {
        if (!gnbSub || gnbSub === currentSub) return;
        clearTimeout(closeTimer);

        // 열려 있던 서브의 현재 높이를 이어받아 접힘 없이 전환 (닫히는 중인 서브는 높이 승계 제외)
        let startHeight = 0;
        gnbSubs.forEach((sub) => {
            if (sub === gnbSub || sub.style.visibility !== "visible") return;
            if (!sub.classList.contains("is-closing")) {
                startHeight = Math.max(startHeight, sub.getBoundingClientRect().height);
            }
            setInstant(sub, "0", "hidden");
        });

        // 컬럼 fade-down 재시작 (아래 setInstant의 reflow로 애니메이션 리셋)
        gnbSub.classList.remove("on");

        // 높이가 고정된 상태에선 scrollHeight가 실제 컨텐츠보다 클 수 있어 auto로 측정
        setInstant(gnbSub, "auto", "visible");
        const targetHeight = gnbSub.offsetHeight;
        setInstant(gnbSub, startHeight + "px", "visible");
        gnbSub.style.height = targetHeight + "px";
        gnbSub.classList.add("on");
        if (header) header.classList.add("gnb-open");
        pcGnbList.forEach((item) => item.classList.toggle("on", item.contains(gnbSub)));
        currentSub = gnbSub;
    };

    const closeGnbSub = () => {
        if (!currentSub) return;
        const gnbSub = currentSub;

        // 아래→위로 걷히며 fade-out 후 숨김
        gnbSub.classList.remove("on");
        gnbSub.classList.add("is-closing");
        clearTimeout(closeTimer);
        closeTimer = setTimeout(() => {
            setInstant(gnbSub, "0", "hidden");
            // 닫힘 효과가 끝난 뒤 z-index 원복
            if (header) header.classList.remove("gnb-open");
        }, CLOSE_DURATION);

        pcGnbList.forEach((item) => item.classList.remove("on"));
        currentSub = null;
    };

    pcGnbList.forEach((item) => {
        const gnbSub = item.querySelector(".gnb-sub");
        if (!gnbSub) return;

        item.addEventListener("mouseenter", () => openGnbSub(gnbSub));
        item.addEventListener("focusin", () => openGnbSub(gnbSub));
    });

    // pc-gnb 영역(1depth 사이 gap 포함)을 벗어날 때까지 열린 상태 유지
    pcGnb.addEventListener("mouseleave", () => {
        // 클릭으로 생긴 포커스는 무시하고, 키보드 포커스가 남아 있을 때만 유지
        const focused = document.activeElement;
        if (pcGnb.contains(focused) && focused.matches(":focus-visible")) return;
        closeGnbSub();
    });
    pcGnb.addEventListener("focusout", (event) => {
        if (!pcGnb.contains(event.relatedTarget) && !pcGnb.matches(":hover")) closeGnbSub();
    });

    // ESC 키 입력 시 열려있는 PC GNB 서브메뉴 닫기
    document.addEventListener("keydown", (e) => {
        if (e.key === "Escape") closeGnbSub();
    });
}

/* ==========================================================================
   4. 헤더 검색 레이어 토글 (Header Search Layer)
   ========================================================================== */
function initSearchLayer() {
    const searchBtn = document.querySelector(".function-menu .search");
    const searchLayer = document.querySelector(".search-layer");
    if (!searchBtn || !searchLayer) return;

    const searchInput = searchLayer.querySelector(".search-input input[type='text'], input[type='search']");
    const closeBtn = searchLayer.querySelector(".close, .search-close, .btn-close");
    const recommendBtns = searchLayer.querySelectorAll(".recommend-list button");

    const closeSearchLayer = () => {
        searchBtn.classList.remove("act");
        searchBtn.setAttribute("aria-expanded", "false");
        searchLayer.classList.remove("act");
        document.body.classList.remove("no-scroll");
        searchBtn.focus();
    };

    const openSearchLayer = () => {
        searchBtn.classList.add("act");
        searchBtn.setAttribute("aria-expanded", "true");
        searchLayer.classList.add("act");
        document.body.classList.add("no-scroll");

        // 검색창 내부 input 자동 포커스
        if (searchInput) {
            setTimeout(() => searchInput.focus(), 100);
        }

        // 모바일 메뉴가 열려 있다면 닫기
        const moGnbBtn = document.querySelector(".mo-menu");
        const moGnb = document.querySelector(".mo-gnb");
        const header = document.querySelector("header");
        if (moGnbBtn && moGnbBtn.classList.contains("act")) {
            moGnbBtn.classList.remove("act");
            moGnbBtn.setAttribute("aria-expanded", "false");
            moGnb.classList.remove("act");
            if (header) header.classList.remove("act");
        }
    };

    searchBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        const isOpen = searchLayer.classList.contains("act");
        if (isOpen) {
            closeSearchLayer();
        } else {
            openSearchLayer();
        }
    });

    // 닫기 버튼 클릭 이벤트
    if (closeBtn) {
        closeBtn.addEventListener("click", (e) => {
            e.stopPropagation();
            closeSearchLayer();
        });
    }

    // 추천 검색어를 입력칸에 넣고 검색 버튼을 누른 것과 같이 보낸다
    if (recommendBtns.length && searchInput) {
        recommendBtns.forEach((btn) => {
            btn.addEventListener("click", () => {
                searchInput.value = btn.textContent.trim();
                const form = searchInput.form;
                if (!form) return;
                if (typeof form.requestSubmit === "function") {
                    form.requestSubmit();
                } else {
                    form.submit();
                }
            });
        });
    }

    // ESC 키로 검색 레이어 닫기
    document.addEventListener("keydown", (e) => {
        if (e.key === "Escape" && searchLayer.classList.contains("act")) {
            closeSearchLayer();
        }
    });
}

/* ==========================================================================
   5. 패밀리 사이트 드롭다운 (Family Site Dropdown)
   ========================================================================== */
function initFamilySite() {
    const familySite = document.querySelector(".family-site");
    if (!familySite) return;

    const familySiteBtn = familySite.querySelector("button");
    if (!familySiteBtn) return;

    const closeFamilySite = () => {
        familySite.classList.remove("is-open");
        familySiteBtn.setAttribute("aria-expanded", "false");
    };

    familySiteBtn.addEventListener("click", (event) => {
        event.stopPropagation();
        const isOpen = familySite.classList.toggle("is-open");
        familySiteBtn.setAttribute("aria-expanded", isOpen ? "true" : "false");
    });

    familySite.querySelectorAll("ul a").forEach((link) => {
        link.addEventListener("click", closeFamilySite);
    });

    document.addEventListener("click", (event) => {
        if (!familySite.contains(event.target)) {
            closeFamilySite();
        }
    });

    // 포커스 벗어남 및 ESC 키 처리
    familySite.addEventListener("focusout", (event) => {
        if (!familySite.contains(event.relatedTarget)) {
            closeFamilySite();
        }
    });

    document.addEventListener("keydown", (event) => {
        if (event.key === "Escape" && familySite.classList.contains("is-open")) {
            closeFamilySite();
            familySiteBtn.focus();
        }
    });
}

/* ==========================================================================
   6. 이메일 도메인 선택 (Email Domain Select - 다중 폼 지원)
   ========================================================================== */
function initEmailDomain() {
    const emailContainers = document.querySelectorAll(".email, .form-item.email, .forms-cont");
    if (!emailContainers.length) return;

    emailContainers.forEach((container) => {
        const domainSelect = container.querySelector("select[name='email-domain'], select[name='email-domain-select'], select#email-domain");
        const domainInput = container.querySelector("input[name='email-domain'], input[name='email2']");

        if (domainSelect && domainInput) {
            domainSelect.addEventListener("change", function () {
                if (this.value === "직접입력" || this.value === "") {
                    domainInput.value = "";
                    domainInput.readOnly = false;
                    domainInput.focus();
                } else {
                    domainInput.value = this.value;
                    domainInput.readOnly = true;
                }
            });
        }
    });
}

/* ==========================================================================
   7. 문의하기 유입경로 '기타' 선택 시 추가 인풋 노출 (Inflow Other Input)
   ========================================================================== */
function initInflowSelect() {
    const inflowSelect = document.querySelector("#inflow");
    const inflowOtherInput = document.querySelector("#inflowOther");
    if (!inflowSelect || !inflowOtherInput) return;

    const updateInflowOther = () => {
        if (inflowSelect.value === "17" || inflowSelect.value === "기타") {
            inflowOtherInput.classList.add("show");
            inflowOtherInput.focus();
        } else {
            inflowOtherInput.classList.remove("show");
            inflowOtherInput.value = "";
        }
    };

    inflowSelect.addEventListener("change", updateInflowOther);
}

/* ==========================================================================
   8. 문의구분: IT솔루션 / 웅진그룹 상호 배타 선택 (Inquiry Category Panels)
   ========================================================================== */
function initCategoryPanels() {
    const itCategoryPanel = document.querySelector('.inquiry-form .category-panel[data-panel="it"]');
    const groupCategoryPanel = document.querySelector('.inquiry-form .category-panel[data-panel="group"]');
    if (!itCategoryPanel || !groupCategoryPanel) return;

    const getCategoryChecks = (panel) => panel.querySelectorAll('input[name="categories"], input[name="category"]');
    const hasCheckedCategory = (panel) => [...getCategoryChecks(panel)].some((input) => input.checked);

    const setCategoryChecksDisabled = (panel, disabled) => {
        getCategoryChecks(panel).forEach((input) => {
            if (disabled) input.checked = false;
            input.disabled = disabled;
        });
    };

    const syncCategoryPanels = () => {
        const itChecked = hasCheckedCategory(itCategoryPanel);
        const groupChecked = hasCheckedCategory(groupCategoryPanel);

        setCategoryChecksDisabled(groupCategoryPanel, itChecked);
        setCategoryChecksDisabled(itCategoryPanel, groupChecked);
    };

    [itCategoryPanel, groupCategoryPanel].forEach((panel) => {
        getCategoryChecks(panel).forEach((input) => {
            input.addEventListener("change", syncCategoryPanels);
        });
    });

    // 초기 로딩 시 상태 동기화
    syncCategoryPanels();
}

/* ==========================================================================
   9. 탭 메뉴 & 카테고리 탭 (Tab Menu & Category Tabs)
   ========================================================================== */
function initBridgeTabs() {
    document.querySelectorAll(".bridge-tabs").forEach((tabList) => {
        const bridge = tabList.closest(".bridge-area");
        if (!bridge) return;

        const buttons = tabList.querySelectorAll("button");
        const panels = bridge.querySelectorAll(".bridge-tabs-cont");

        const scrollButtonToStart = (button) => {
            if (!button || window.matchMedia("(min-width: 1025px)").matches) return;

            const left = button.getBoundingClientRect().left - tabList.getBoundingClientRect().left + tabList.scrollLeft;
            const maxLeft = Math.max(0, tabList.scrollWidth - tabList.clientWidth);
            const targetLeft = Math.min(Math.max(0, left), maxLeft);
            if (Math.abs(tabList.scrollLeft - targetLeft) < 1) return;

            tabList.scrollTo({ left: targetLeft, behavior: "smooth" });
        };

        buttons.forEach((button, index) => {
            button.addEventListener("click", () => {
                panels.forEach((panel, panelIndex) => {
                    panel.classList.toggle("hide", panelIndex !== index);
                });
                requestAnimationFrame(() => scrollButtonToStart(button));
            });
        });
    });
}

function initTabMenu() {
    // 1) 카테고리 리스트 (category-list, category-list2) 단순 활성화 토글
    const categoryContainers = document.querySelectorAll(".category-list, .category-list2, .sub-tab-list");
    categoryContainers.forEach((container) => {
        const buttons = container.querySelectorAll("button");
        buttons.forEach((button) => {
            button.addEventListener("click", () => {
                buttons.forEach((btn) => btn.classList.remove("act"));
                button.classList.add("act");
            });
        });
    });

    // 1-1) 모바일 category-list 버튼 5개 이상 — 클릭한 버튼이 왼쪽에 보이도록 가로 스크롤 이동
    document.querySelectorAll(".category-list").forEach((list) => {
        const buttons = list.querySelectorAll("button");
        if (buttons.length < 5) return;

        buttons.forEach((button) => {
            button.addEventListener("click", () => {
                if (window.matchMedia("(min-width: 1025px)").matches) return;
                if (list.scrollWidth <= list.clientWidth) return;

                const left = button.getBoundingClientRect().left - list.getBoundingClientRect().left + list.scrollLeft;
                const maxLeft = Math.max(0, list.scrollWidth - list.clientWidth);
                list.scrollTo({ left: Math.min(Math.max(0, left), maxLeft), behavior: "smooth" });
            });
        });
    });

    // 2) 탭 메뉴 (tab-list) - data-target ↔ tab-cont id 매칭으로 스크롤 이동 및 ScrollSpy
    const tabContainers = document.querySelectorAll(".tab-list");
    tabContainers.forEach((tabContainer) => {
        const tabButtons = Array.from(tabContainer.querySelectorAll("button"));
        if (!tabButtons.length) return;

        // sticky 요소 자체는 스크롤 컨테이너가 되면 아래로 스크롤할 때 고정이 풀린다
        let tabScroller = tabContainer.querySelector(":scope > .tab-scroll");
        if (!tabScroller) {
            tabScroller = document.createElement("div");
            tabScroller.className = "tab-scroll";
            while (tabContainer.firstChild) tabScroller.appendChild(tabContainer.firstChild);
            tabContainer.appendChild(tabScroller);
        }

        const parentSection = tabContainer.closest(".inner-cont, .content, main") || document;
        const fallbackContents = Array.from(parentSection.querySelectorAll(".tab-cont"));

        const getTargetCont = (button, index) => {
            const targetId = (button.getAttribute("data-target") || "").replace(/^#/, "");
            if (targetId) {
                const byId = document.getElementById(targetId);
                if (byId) return byId;
            }
            return fallbackContents[index] || null;
        };

        const tabTargets = tabButtons
            .map((button, index) => ({ button, cont: getTargetCont(button, index) }))
            .filter((item) => item.cont);

        const isType2 = tabContainer.classList.contains("type2");
        const SPY_THRESHOLD = 30;
        let isClickScrolling = false;
        let clickedButton = null;

        const setActiveTab = (activeButton) => {
            if (activeButton.classList.contains("act")) return;
            tabButtons.forEach((btn) => {
                btn.classList.toggle("act", btn === activeButton);
            });
            scrollTabIntoView(activeButton);
        };

        // 모바일 가로 스크롤 탭 — 활성 탭이 보이도록 탭 영역만 가로 이동 (scrollIntoView는 세로 스크롤까지 발생하여 사용 안 함)
        const scrollTabIntoView = (button) => {
            if (tabContainer.scrollWidth <= tabContainer.clientWidth) return;
            const left = button.offsetLeft - (tabContainer.clientWidth - button.offsetWidth) / 2;
            tabContainer.scrollTo({ left: Math.max(0, left), behavior: "smooth" });
        };

        // 모바일: 활성 버튼이 스크롤 범위 안에서 가장 왼쪽에 오도록 가로 스크롤
        const scrollTabToStart = (button, behavior = "smooth") => {
            if (!button || window.matchMedia("(min-width: 1025px)").matches) return;

            const left = button.getBoundingClientRect().left - tabScroller.getBoundingClientRect().left + tabScroller.scrollLeft;
            const maxLeft = Math.max(0, tabScroller.scrollWidth - tabScroller.clientWidth);
            const targetLeft = Math.min(Math.max(0, left), maxLeft);
            if (Math.abs(tabScroller.scrollLeft - targetLeft) < 1) return;

            if (behavior === "auto") {
                tabScroller.scrollLeft = targetLeft;
                return;
            }

            tabScroller.scrollTo({ left: targetLeft, behavior });
        };

        const alignActiveTab = (behavior = "auto") => {
            scrollTabToStart(tabContainer.querySelector("button.act"), behavior);
        };

        // 도착 스크롤 위치 — type2·첫 번째 컨텐츠는 탭이 --sticky-tab-top에 고정되는 위치, 나머지는 컨텐츠 상단이 탭 바로 아래
        const getTargetScrollTop = (targetCont, index, isHeaderHidden) => {
            const tabTop = getStickyTabTop(tabContainer, isHeaderHidden);
            return isType2 || index === 0
                ? getStickyNaturalTop(tabContainer) - tabTop
                : getDocTop(targetCont) - tabTop - tabContainer.offsetHeight;
        };

        const scrollToContent = (targetCont, index, forceHeaderHidden) => {
            isClickScrolling = true;
            scrollWithHeader(
                (isHeaderHidden) => getTargetScrollTop(targetCont, index, isHeaderHidden),
                () => {
                    isClickScrolling = false;
                    // 페이지 하단 등 목표까지 스크롤이 닿지 않아도 클릭한 탭 유지
                    if (clickedButton) setActiveTab(clickedButton);
                },
                forceHeaderHidden ? { forceHeaderHidden: true } : undefined
            );
        };

        tabButtons.forEach((button, index) => {
            button.addEventListener("click", () => {
                setActiveTab(button);
                scrollTabToStart(button);

                const targetCont = getTargetCont(button, index);
                if (!targetCont) return;

                clickedButton = button;

                if (isType2) {
                    fallbackContents.forEach((cont) => {
                        cont.classList.toggle("hide", cont !== targetCont);
                    });

                    requestAnimationFrame(() => {
                        requestAnimationFrame(() => scrollToContent(targetCont, index, true));
                    });
                    return;
                }

                scrollToContent(targetCont, index);
            });
        });

        // 페이지 스크롤 시 현재 보고 있는 tab-cont 섹션에 맞춰 tab 버튼 활성화 (ScrollSpy)
        // 모바일에서는 활성 버튼이 왼쪽 끝에 오도록 가로 위치도 맞춘다
        const onScroll = () => {
            if (!isClickScrolling && tabTargets.length > 0 && !isType2) {
                clickedButton = null;

                const line = getStickyTabTop(tabContainer) + tabContainer.offsetHeight + SPY_THRESHOLD;
                let activeButton = tabTargets[0].button;

                tabTargets.forEach(({ button, cont }) => {
                    if (cont.getBoundingClientRect().top <= line) {
                        activeButton = button;
                    }
                });

                // 페이지 최하단 도달 시 마지막 탭 활성 (마지막 컨텐츠가 짧아 기준선에 닿지 않는 경우)
                if (window.scrollY > 0 && window.scrollY >= getMaxScroll() - 2) {
                    activeButton = tabTargets[tabTargets.length - 1].button;
                }

                setActiveTab(activeButton);
            }

            alignActiveTab("auto");
        };

        window.addEventListener("scroll", onScroll, { passive: true });
        window.addEventListener("resize", onScroll);
        onScroll();
    });
}

/* ==========================================================================
   9-1. 회사정보 탭 (Company Tab)
   ========================================================================== */
function initCompanyTab() {
    const tabContainers = document.querySelectorAll(".company-tab");
    if (!tabContainers.length) return;

    tabContainers.forEach((tabContainer) => {
        const buttons = Array.from(tabContainer.querySelectorAll("button"));
        if (!buttons.length) return;

        const scroller = tabContainer.querySelector(":scope > .tab-scroll");

        const alignButton = (button, behavior = "auto") => {
            if (!button || !scroller || window.matchMedia("(min-width: 1025px)").matches) return;

            const scrollerRect = scroller.getBoundingClientRect();
            const btnRect = button.getBoundingClientRect();
            const overflowLeft = scrollerRect.left - btnRect.left;
            const overflowRight = btnRect.right - scrollerRect.right;
            let next = scroller.scrollLeft;

            if (overflowLeft > 1) next -= overflowLeft;
            else if (overflowRight > 1) next += overflowRight;

            const maxLeft = Math.max(0, scroller.scrollWidth - scroller.clientWidth);
            next = Math.min(Math.max(0, next), maxLeft);
            if (Math.abs(scroller.scrollLeft - next) < 1) return;

            if (behavior === "auto") {
                scroller.scrollLeft = next;
                return;
            }

            scroller.scrollTo({ left: next, behavior });
        };

        const companyCont = tabContainer.nextElementSibling && tabContainer.nextElementSibling.classList.contains("company-cont")
            ? tabContainer.nextElementSibling
            : (tabContainer.parentElement ? tabContainer.parentElement.querySelector(".company-cont") : null);
        const tabContents = companyCont ? Array.from(companyCont.querySelectorAll(".tab-cont")) : [];

        // type2 tab-list와 동일: 탭 sticky 위치로 이동 + 이동 중 헤더 숨김 고정
        const scrollToContent = () => {
            scrollWithHeader(
                (isHeaderHidden) => getStickyNaturalTop(tabContainer) - getStickyTabTop(tabContainer, isHeaderHidden),
                undefined,
                { forceHeaderHidden: true }
            );
        };

        buttons.forEach((button) => {
            button.addEventListener("click", () => {
                buttons.forEach((btn) => btn.classList.remove("act"));
                button.classList.add("act");
                alignButton(button, "smooth");

                const targetId = (button.getAttribute("data-target") || "").trim().replace(/^#/, "");
                if (targetId) {
                    const targetCont = document.getElementById(targetId);
                    if (targetCont && targetCont.classList.contains("tab-cont")) {
                        tabContents.forEach((cont) => cont.classList.remove("act"));
                        targetCont.classList.add("act");
                    }

                    requestAnimationFrame(() => {
                        requestAnimationFrame(scrollToContent);
                    });
                }
            });
        });

        // 하위 버튼 5개 이상 — 로드 시 'act' 버튼이 왼쪽에 보이도록 가로 스크롤 이동
        const scrollActToStart = () => {
            const actButton = tabContainer.querySelector("button.act");
            const list = scroller || tabContainer;
            if (!actButton || window.matchMedia("(min-width: 1025px)").matches) return;
            if (list.scrollWidth <= list.clientWidth) return;

            const left = actButton.getBoundingClientRect().left - list.getBoundingClientRect().left + list.scrollLeft;
            const maxLeft = Math.max(0, list.scrollWidth - list.clientWidth);
            list.scrollTo({ left: Math.min(Math.max(0, left), maxLeft), behavior: "smooth" });
        };

        if (buttons.length >= 5) {
            if (document.readyState === "complete") {
                requestAnimationFrame(scrollActToStart);
            } else {
                window.addEventListener("load", scrollActToStart, { once: true });
            }
        } else {
            requestAnimationFrame(() => alignButton(tabContainer.querySelector("button.act")));
        }
    });
}

/* ==========================================================================
   10. FAQ 아코디언 (FAQ Accordion)
   ========================================================================== */
function initFaqAccordion() {
    const faqLists = document.querySelectorAll(".faq .faq-list, .history > .history-list");
    if (!faqLists.length) return;

    faqLists.forEach((list) => {
        const items = list.querySelectorAll(":scope > .faq-item, :scope > .history-item");

        items.forEach((item) => {
            const head = item.querySelector(".item-head");
            const cont = item.querySelector(".item-cont");
            if (!head || !cont) return;

            const isOpen = head.classList.contains("act") || cont.classList.contains("act");
            head.classList.toggle("act", isOpen);
            cont.classList.toggle("act", isOpen);
            head.setAttribute("aria-expanded", isOpen ? "true" : "false");

            head.addEventListener("click", (e) => {
                e.preventDefault();
                const willOpen = !head.classList.contains("act");

                items.forEach((other) => {
                    if (other === item) return;
                    const otherHead = other.querySelector(".item-head");
                    const otherCont = other.querySelector(".item-cont");
                    // if (otherHead) {
                    //     otherHead.classList.remove("act");
                    //     otherHead.setAttribute("aria-expanded", "false");
                    // }
                    // if (otherCont) otherCont.classList.remove("act");
                });

                head.classList.toggle("act", willOpen);
                cont.classList.toggle("act", willOpen);
                head.setAttribute("aria-expanded", willOpen ? "true" : "false");
            });
        });
    });
}

/* ==========================================================================
   11. 프로젝트 사례 아코디언 (Project Case Accordion)
   ========================================================================== */
function initProjectCaseAccordion() {
    // .faq.project-case 는 initFaqAccordion 에서 이미 바인딩하므로 제외
    const projectLists = document.querySelectorAll(".project-case:not(.faq) .project-list");
    if (!projectLists.length) return;

    projectLists.forEach((list) => {
        const items = list.querySelectorAll(".project-item");

        items.forEach((item) => {
            const head = item.querySelector(".item-head");
            const cont = item.querySelector(".item-cont");
            if (!head || !cont) return;

            const isOpen = head.classList.contains("act") || cont.classList.contains("act");
            head.classList.toggle("act", isOpen);
            cont.classList.toggle("act", isOpen);
            head.setAttribute("aria-expanded", isOpen ? "true" : "false");

            head.addEventListener("click", (e) => {
                e.preventDefault();
                const willOpen = !head.classList.contains("act");

                head.classList.toggle("act", willOpen);
                cont.classList.toggle("act", willOpen);
                head.setAttribute("aria-expanded", willOpen ? "true" : "false");
            });
        });
    });
}

/* ==========================================================================
   12. 레이어 팝업 열기 / 닫기 (Layer Popup - Global Functions)
   ========================================================================== */
function syncBodyScrollForPopups() {
    const hasActivePopup = document.querySelector(".layer-pop.act");
    if (hasActivePopup) {
        document.body.classList.add("no-scroll");
    } else {
        document.body.classList.remove("no-scroll");
    }
}

/**
 * 레이어 팝업 열기
 * @param {string} popup - 열고자 하는 레이어 팝업 클래스명 (예: 'download', 'terms1')
 * @param {Event} [event] - 클릭 이벤트 객체 (선택)
 */
const openLayer = (popup, event) => {
    if (event) {
        event.preventDefault();
        event.stopPropagation();
    }

    const target = document.querySelector(".layer-pop." + popup);
    if (!target) return;

    target.classList.add("act");
    syncBodyScrollForPopups();

    // 접근성: 팝업 내부 첫 포커스 가능한 요소로 포커스 이동
    const focusable = target.querySelector("button, [href], input, select, textarea, [tabindex]:not([tabindex='-1'])");
    if (focusable) {
        setTimeout(() => focusable.focus(), 100);
    }
};

/**
 * 레이어 팝업 닫기
 * @param {HTMLElement|string} el - 닫기 버튼 엘리먼트 또는 팝업 선택자
 */
const closeLayer = (el) => {
    let target;
    if (typeof el === "string") {
        target = document.querySelector(".layer-pop." + el);
    } else if (el instanceof HTMLElement) {
        target = el.closest(".layer-pop");
    }

    if (!target) return;

    target.classList.remove("act");
    syncBodyScrollForPopups();
};

// 인라인 onclick 등 전역 호출을 위해 window 객체에 등록
window.openLayer = openLayer;
window.closeLayer = closeLayer;

/* ==========================================================================
   13. 레이어 팝업 이벤트 바인딩 (배경 클릭, 취소 버튼, ESC 키)
   ========================================================================== */
function initLayerPopupEvents() {
    const popups = document.querySelectorAll(".layer-pop");
    popups.forEach((pop) => {
        // 팝업 배경(딤드 영역) 클릭 시 닫기
        // 메인 팝업은 딤이 맨 뒤 레이어에만 있으므로, 여러 개면 맨 앞 팝업을 닫는다
        pop.addEventListener("click", (e) => {
            if (e.target !== pop) return;
            if (pop.classList.contains("home")) {
                const activeHomes = document.querySelectorAll(".layer-pop.home.act");
                const top = activeHomes[activeHomes.length - 1];
                if (top) closeLayer(top);
                return;
            }
            closeLayer(pop);
        });

        // 팝업 내부 취소 버튼 클릭 시 닫기
        const cancelBtn = pop.querySelector(".pop-foot .btn-outline-default");
        if (cancelBtn) {
            cancelBtn.addEventListener("click", () => {
                closeLayer(pop);
            });
        }
    });

    // ESC 키로 활성화된 최상단 레이어 팝업 닫기
    document.addEventListener("keydown", (e) => {
        if (e.key === "Escape") {
            const activePopups = document.querySelectorAll(".layer-pop.act");
            if (activePopups.length > 0) {
                const topPopup = activePopups[activePopups.length - 1];
                closeLayer(topPopup);
            }
        }
    });
}

/* ==========================================================================
   14. 산업 페이지 슬라이더 (Project Cases / Services)
   ========================================================================== */
function initIndustrySliders() {
    if (typeof Swiper === "undefined") return;

    document.querySelectorAll(".project-slider").forEach((slider) => {
        const swiperEl = slider.querySelector(".swiper");
        if (!swiperEl) return;

        new Swiper(swiperEl, {
            slidesPerView: 2,
            spaceBetween: 10,
            loop: true,
            watchOverflow: true,
            observer: true,
            observeParents: true,
            pagination: {
                el: slider.querySelector(".swiper-pagination"),
                clickable: true
            },
            navigation: {
                prevEl: slider.querySelector(".project-slider-prev"),
                nextEl: slider.querySelector(".project-slider-next")
            },
            breakpoints: {
                1025: {
                    slidesPerView: 3,
                    spaceBetween: 20
                }
            }
        });
    });

    document.querySelectorAll(".services-slider").forEach((slider) => {
        const swiperEl = slider.querySelector(".swiper");
        if (!swiperEl) return;

        const mobileQuery = window.matchMedia("(max-width: 1024px)");
        let servicesSwiper = null;

        const createServicesSwiper = () => {
            if (servicesSwiper) {
                servicesSwiper.destroy(true, true);
                servicesSwiper = null;
            }

            if (mobileQuery.matches) {
                servicesSwiper = new Swiper(swiperEl, {
                    loop: true,
                    slidesPerView: 1,
                    spaceBetween: 10,
                    grid: {
                        rows: 2,
                        fill: "column"
                    },
                    watchOverflow: true,
                    observer: true,
                    observeParents: true,
                    pagination: {
                        el: slider.querySelector(".swiper-pagination"),
                        clickable: true
                    }
                });
                return;
            }

            const paginationEl = slider.querySelector(".swiper-pagination");
            if (paginationEl) paginationEl.innerHTML = "";

            servicesSwiper = new Swiper(swiperEl, {
                loop: true,
                slidesPerView: 3,
                spaceBetween: 20,
                watchOverflow: true,
                observer: true,
                observeParents: true,
                navigation: {
                    prevEl: slider.querySelector(".services-slider-prev"),
                    nextEl: slider.querySelector(".services-slider-next")
                }
            });
        };

        createServicesSwiper();
        mobileQuery.addEventListener("change", createServicesSwiper);
    });
}

/* ==========================================================================
   15. 모바일·태블릿 서비스 목록 순차 강조 (Service Item Cycle)
   ========================================================================== */
function initServiceItemCycle() {
    const lists = document.querySelectorAll(".service-list");
    if (!lists.length) return;

    const cycleQuery = window.matchMedia("(max-width: 1439px)");
    const interval = 3000;
    const timers = new Map();

    const getItems = (list) => list.querySelectorAll(":scope > .service-item");

    const clearOn = (list) => {
        getItems(list).forEach((item) => item.classList.remove("on"));
    };

    const stop = (list) => {
        const timer = timers.get(list);
        if (timer) {
            clearInterval(timer);
            timers.delete(list);
        }
        clearOn(list);
    };

    const start = (list) => {
        const items = getItems(list);
        if (!items.length || timers.has(list)) return;

        let index = 0;
        const activate = () => {
            items.forEach((item, i) => item.classList.toggle("on", i === index));
            index = (index + 1) % items.length;
        };

        activate();
        timers.set(list, setInterval(activate, interval));
    };

    const sync = () => {
        lists.forEach((list) => {
            if (!getItems(list).length) return;
            if (cycleQuery.matches) {
                start(list);
            } else {
                stop(list);
            }
        });
    };

    if (typeof cycleQuery.addEventListener === "function") {
        cycleQuery.addEventListener("change", sync);
    } else {
        cycleQuery.addListener(sync);
    }

    sync();
}

/* ==========================================================================
   16. 페이지 최상단 이동 버튼 (Scroll To Top)
   ========================================================================== */
function initScrollTop() {
    const scrollAction = document.querySelector(".scroll-action");
    const btnTop = scrollAction && scrollAction.querySelector(".scroll-top");
    if (!scrollAction || !btnTop) return;

    const header = document.querySelector("header");

    const sync = () => {
        const threshold = header ? header.offsetHeight : 0;
        scrollAction.classList.toggle("is-top-visible", window.scrollY >= threshold);
    };

    btnTop.addEventListener("click", () => {
        window.scrollTo({ top: 0, behavior: "smooth" });
    });

    window.addEventListener("scroll", sync, { passive: true });
    window.addEventListener("resize", sync, { passive: true });
    sync();
}

